// --- Validate & normalise input ---
const body = $json.body || $json;
let phone = String(body.phone || '').trim();
const amount = parseInt(body.amount, 10);
const reference = String(body.reference || 'ORDER-' + Date.now()).slice(0, 12);
const description = String(body.description || 'Payment').slice(0, 13);

// Normalise phone to 2547XXXXXXXX / 2541XXXXXXXX
phone = phone.replace(/[^0-9]/g, '');
if (phone.startsWith('0')) phone = '254' + phone.slice(1);
if (phone.startsWith('+')) phone = phone.slice(1);
if (phone.startsWith('7') || phone.startsWith('1')) phone = '254' + phone;

if (!/^254(7|1)\d{8}$/.test(phone)) {
  throw new Error('Invalid phone number. Use 2547XXXXXXXX format. Got: ' + phone);
}
if (!amount || amount < 1) {
  throw new Error('Amount must be a positive integer');
}

return [{ json: { phone, amount, reference, description } }];

// --- Build STK Push payload ---
const input = $('Validate Input').item.json;
const token = $json.access_token;

const shortcode = $env.MPESA_SHORTCODE || '174379';
const passkey = $env.MPESA_PASSKEY;
const callbackBase = $env.MPESA_CALLBACK_BASE_URL;
const baseUrl = $env.MPESA_BASE_URL || 'https://sandbox.safaricom.co.ke';

if (!passkey) throw new Error('MPESA_PASSKEY env var not set');
if (!callbackBase) throw new Error('MPESA_CALLBACK_BASE_URL env var not set');

// Timestamp: YYYYMMDDHHmmss (Africa/Nairobi)
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
// n8n container TZ is set to Africa/Nairobi in docker-compose
const timestamp =
  now.getFullYear().toString() +
  pad(now.getMonth() + 1) +
  pad(now.getDate()) +
  pad(now.getHours()) +
  pad(now.getMinutes()) +
  pad(now.getSeconds());

const password = Buffer.from(shortcode + passkey + timestamp).toString('base64');

return [{
  json: {
    url: `${baseUrl}/mpesa/stkpush/v1/processrequest`,
    authHeader: `Bearer ${token}`,
    payload: {
      BusinessShortCode: parseInt(shortcode, 10),
      Password: password,
      Timestamp: timestamp,
      TransactionType: 'CustomerPayBillOnline',
      Amount: input.amount,
      PartyA: parseInt(input.phone, 10),
      PartyB: parseInt(shortcode, 10),
      PhoneNumber: parseInt(input.phone, 10),
      CallBackURL: `${callbackBase}/webhook/mpesa/stk-callback`,
      AccountReference: input.reference,
      TransactionDesc: input.description
    }
  }
}];

const resp = $('POST /stkpush').item.json;
const input = $('Validate Input').item.json;

return [{
  json: {
    success: resp.ResponseCode === '0',
    message: resp.CustomerMessage || resp.errorMessage || 'Unknown',
    checkout_request_id: resp.CheckoutRequestID,
    merchant_request_id: resp.MerchantRequestID,
    reference: input.reference,
    phone: input.phone,
    amount: input.amount
  }
}];
